(() => {
  const form=document.getElementById('charterEditor'),root=document.getElementById('chapterEditor');
  if(!form||!root)return;
  function field(label,value,kind='input') {const wrap=document.createElement('div');wrap.className='mb-3';const l=document.createElement('label'),el=document.createElement(kind);el.className='form-control';el.value=value;el.required=kind==='input';el.maxLength=kind==='input'?180:12000;el.id='charter-field-'+crypto.randomUUID();l.htmlFor=el.id;l.textContent=label;wrap.append(l,el);return wrap;}
  function button(label,action){const b=document.createElement('button');b.type='button';b.className='btn btn-sm btn-outline-secondary';b.textContent=label;b.addEventListener('click',action);return b;}
  function subsection(data={title:'',body:''}){const node=document.createElement('div');node.className='charter-subchapter';node.append(field('Titre du sous-chapitre',data.title),field('Contenu',data.body,'textarea'),button('Retirer ce sous-chapitre',()=>{if(confirm('Retirer ce sous-chapitre du brouillon ?'))node.remove();}));return node;}
  function chapter(data={title:'',body:'',children:[]}) {const node=document.createElement('section');node.className='charter-chapter';const head=document.createElement('header'),title=document.createElement('strong'),actions=document.createElement('div');title.textContent='Chapitre';actions.className='charter-actions';actions.append(button('Monter',()=>{if(node.previousElementSibling)root.insertBefore(node,node.previousElementSibling);}),button('Descendre',()=>{if(node.nextElementSibling)root.insertBefore(node.nextElementSibling,node);}),button('Retirer',()=>{if(confirm('Retirer ce chapitre du brouillon ?'))node.remove();}));head.append(title,actions);node.append(head,field('Titre du chapitre',data.title),field('Texte introductif',data.body,'textarea'));const children=document.createElement('div');children.className='charter-children';(data.children||[]).forEach(c=>children.append(subsection(c)));node.append(children,button('Ajouter un sous-chapitre',()=>children.append(subsection())));return node;}
  JSON.parse(root.dataset.content).forEach(c=>root.append(chapter(c)));
  document.getElementById('addChapter').addEventListener('click',()=>{const c=chapter();root.append(c);c.querySelector('input').focus();});
  form.addEventListener('submit',e=>{const chapters=[...root.children].map(c=>({title:c.querySelector(':scope > .mb-3 input').value,body:c.querySelector(':scope > .mb-3 textarea').value,children:[...c.querySelectorAll('.charter-subchapter')].map(s=>({title:s.querySelector('input').value,body:s.querySelector('textarea').value}))}));if(!chapters.length){e.preventDefault();alert('Ajoutez au moins un chapitre.');return;}document.getElementById('chaptersValue').value=JSON.stringify(chapters);});
  if(window.flatpickr)flatpickr('#charterDate',{locale:'fr',dateFormat:'Y-m-d',altInput:true,altFormat:'d F Y',allowInput:true});
})();
